scripts.content:
// 预设自带的脚本：发送前给请求加一句、注入一条提示词、在“扩展设置”里放自己的设置界面
$('body').append('<div id="e2e-preset-script" hidden>预设脚本</div>');
eventOn(tavern_events.CHAT_COMPLETION_SETTINGS_READY, (data) => {
  data.messages.push({ role: 'system', content: '预设脚本加的一句' });
});
injectPrompts([{ id: 'e2e-inject', position: 'in_chat', depth: 0, role: 'system', content: '注入的提示词' }]);
eventOn(tavern_events.CHAT_CHANGED, () => {
  injectPrompts([{ id: 'e2e-inject', position: 'in_chat', depth: 0, role: 'system', content: '注入的提示词' }]);
});
$('#extensions_settings2').append('<div class="inline-drawer" id="e2e-preset-settings"><div class="inline-drawer-toggle inline-drawer-header"><b>预设脚本设置</b><div class="inline-drawer-icon fa-solid fa-circle-chevron-down down"></div></div><div class="inline-drawer-content"><label class="checkbox_label"><input type="checkbox" id="e2e-preset-opt"><span>预设脚本的选项</span></label></div></div>');
